This Terraform configuration creates a basic AWS SQL database using Amazon RDS MySQL. It includes:

- AWS provider configuration in `us-east-1`
- A small custom VPC with two public subnets
- Internet gateway and route table
- Security group allowing MySQL access on port `3306`
- Randomly generated RDS master password
- Amazon RDS MySQL instance
- Outputs for the database endpoint, username, database name, and password

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Name of the initial database to create."
  type        = string
  default     = "basicdb"
}

